/**
 * Shared theme configuration, defaults, cookie helpers and validation
 * used both during SSR (root layout) and by the `/theme` editor route.
 */

export interface Theme {
  primaryColor: string;
  fontSize: string;
  borderRadius: string;
}

/** Name of the cookie used to persist the user's theme customizations. */
export const THEME_COOKIE_NAME = "user_theme";

/** Fallback theme values used when no (valid) cookie is present. */
export const DEFAULT_THEME: Theme = {
  primaryColor: "#00bcd4",
  fontSize: "16px",
  borderRadius: "4px",
};

/** Hex color, e.g. `#f00` or `#ff0000`. */
const HEX_COLOR_REGEX = /^#(?:[0-9a-fA-F]{3}|[0-9a-fA-F]{6})$/;

/** CSS length, e.g. `16px`, `1.5rem`, `2em`. */
const LENGTH_REGEX = /^\d+(?:\.\d+)?(?:px|rem|em)$/;

/** CSS length or percentage, e.g. `4px`, `0.5rem`, `50%`. */
const LENGTH_OR_PERCENT_REGEX = /^\d+(?:\.\d+)?(?:px|rem|em|%)$/;

export function isValidPrimaryColor(value: string): boolean {
  return HEX_COLOR_REGEX.test(value.trim());
}

export function isValidFontSize(value: string): boolean {
  return LENGTH_REGEX.test(value.trim());
}

export function isValidBorderRadius(value: string): boolean {
  return LENGTH_OR_PERCENT_REGEX.test(value.trim());
}

/**
 * Validates a candidate theme object (e.g. parsed form data).
 * Returns the name of the first invalid field, or `null` if everything is valid.
 */
export function findInvalidField(candidate: {
  primaryColor: string;
  fontSize: string;
  borderRadius: string;
}): "primaryColor" | "fontSize" | "borderRadius" | null {
  if (!isValidPrimaryColor(candidate.primaryColor)) {
    return "primaryColor";
  }
  if (!isValidFontSize(candidate.fontSize)) {
    return "fontSize";
  }
  if (!isValidBorderRadius(candidate.borderRadius)) {
    return "borderRadius";
  }
  return null;
}

/**
 * Safely parses the raw `user_theme` cookie value into a `Theme`, falling
 * back to defaults for any missing/invalid field or JSON parse failure.
 */
export function parseThemeCookie(raw: string | undefined | null): Theme {
  if (!raw) {
    return { ...DEFAULT_THEME };
  }

  try {
    const parsed = JSON.parse(raw);

    const primaryColor =
      typeof parsed?.primaryColor === "string" &&
      isValidPrimaryColor(parsed.primaryColor)
        ? parsed.primaryColor
        : DEFAULT_THEME.primaryColor;

    const fontSize =
      typeof parsed?.fontSize === "string" && isValidFontSize(parsed.fontSize)
        ? parsed.fontSize
        : DEFAULT_THEME.fontSize;

    const borderRadius =
      typeof parsed?.borderRadius === "string" &&
      isValidBorderRadius(parsed.borderRadius)
        ? parsed.borderRadius
        : DEFAULT_THEME.borderRadius;

    return { primaryColor, fontSize, borderRadius };
  } catch {
    return { ...DEFAULT_THEME };
  }
}

/** Builds the `:root { --primary-color: ...; }` CSS text for a given theme. */
export function themeToStyleString(theme: Theme): string {
  return `:root {\n  --primary-color: ${theme.primaryColor};\n  --font-size: ${theme.fontSize};\n  --border-radius: ${theme.borderRadius};\n}`;
}

import { component$, Slot } from "@builder.io/qwik";
import { routeLoader$, type DocumentHead } from "@builder.io/qwik-city";
import {
  parseThemeCookie,
  THEME_COOKIE_NAME,
  themeToStyleString,
} from "~/lib/theme";

/**
 * Reads the `user_theme` cookie during SSR and resolves it (falling back to
 * defaults) so it can be injected as CSS custom properties in the `<head>`.
 *
 * Exported so nested routes (e.g. `/theme`) can reuse the same resolved
 * value via `useThemeLoader()` without re-reading/parsing the cookie.
 */
export const useThemeLoader = routeLoader$(({ cookie }) => {
  const raw = cookie.get(THEME_COOKIE_NAME)?.value;
  return parseThemeCookie(raw);
});

export const head: DocumentHead = ({ resolveValue }) => {
  const theme = resolveValue(useThemeLoader);

  return {
    styles: [
      {
        key: "theme-variables",
        props: { id: "theme-variables" },
        style: themeToStyleString(theme),
      },
    ],
  };
};

export default component$(() => {
  return <Slot />;
});

import { component$ } from "@builder.io/qwik";
import {
  routeLoader$,
  type DocumentHead,
  type RequestHandler,
} from "@builder.io/qwik-city";
import {
  findInvalidField,
  parseThemeCookie,
  THEME_COOKIE_NAME,
  type Theme,
} from "~/lib/theme";

const FORM_ERROR_KEY = "theme-form-error";

/**
 * Handles the theme editor form submission.
 *
 * A plain `<form method="post">` is used (rather than `routeAction$`) so
 * that a bare HTTP POST to `/theme` is validated and processed correctly,
 * with no client-side JavaScript required.
 */
export const onPost: RequestHandler = async (requestEvent) => {
  const body = (await requestEvent.parseBody()) as Record<string, unknown>;

  const candidate = {
    primaryColor: String(body?.primaryColor ?? "").trim(),
    fontSize: String(body?.fontSize ?? "").trim(),
    borderRadius: String(body?.borderRadius ?? "").trim(),
  };

  const invalidField = findInvalidField(candidate);

  if (invalidField) {
    requestEvent.status(400);
    requestEvent.sharedMap.set(FORM_ERROR_KEY, `invalid ${invalidField}`);
    // Falls through to render the page (with the 400 status already set)
    // so the error message can be shown to the user.
    return;
  }

  const theme: Theme = candidate;
  requestEvent.cookie.set(THEME_COOKIE_NAME, JSON.stringify(theme), {
    path: "/",
  });

  throw requestEvent.redirect(302, "/theme");
};

export const useThemeData = routeLoader$((requestEvent) => {
  const raw = requestEvent.cookie.get(THEME_COOKIE_NAME)?.value;
  const theme = parseThemeCookie(raw);
  const error = requestEvent.sharedMap.get(FORM_ERROR_KEY) as
    | string
    | undefined;
  return { theme, error: error ?? null };
});

export default component$(() => {
  const data = useThemeData();
  const { theme, error } = data.value;

  return (
    <>
      <h1>Theme Editor</h1>

      {error && <p style={{ color: "red" }}>{error}</p>}

      <form method="post">
        <div>
          <label for="primaryColor">Primary Color</label>
          <input
            id="primaryColor"
            type="text"
            name="primaryColor"
            value={theme.primaryColor}
          />
        </div>

        <div>
          <label for="fontSize">Font Size</label>
          <input
            id="fontSize"
            type="text"
            name="fontSize"
            value={theme.fontSize}
          />
        </div>

        <div>
          <label for="borderRadius">Border Radius</label>
          <input
            id="borderRadius"
            type="text"
            name="borderRadius"
            value={theme.borderRadius}
          />
        </div>

        <button type="submit">Save Theme</button>
      </form>

      <form method="post" action="/theme/reset">
        <button type="submit">Reset to Defaults</button>
      </form>
    </>
  );
});

export const head: DocumentHead = {
  title: "Theme Editor",
  meta: [
    {
      name: "description",
      content: "Customize your visual theme preferences",
    },
  ],
};

import type { RequestHandler } from "@builder.io/qwik-city";
import { THEME_COOKIE_NAME } from "~/lib/theme";

/**
 * Clears the `user_theme` cookie, restoring the default theme values,
 * then redirects back to the theme editor.
 */
export const onPost: RequestHandler = async (requestEvent) => {
  requestEvent.cookie.delete(THEME_COOKIE_NAME, { path: "/" });
  throw requestEvent.redirect(302, "/theme");
};

